new=r'''void tst_QUrlInternal::decodeForLocalFile_data()
{
    // a null expected string means qt_urlRecode() must fail
    QTest::addColumn<QString>("input");
    QTest::addColumn<QString>("expected");

    const QString fail;

    // nothing to decode
    QTest::newRow("empty") << QString() << QString();
    QTest::newRow("no-percent") << u"/tmp/foo bar"_s << u"/tmp/foo bar"_s;
    QTest::newRow("unicode") << u"/tmp/\u00e9\U0001F600"_s << u"/tmp/\u00e9\U0001F600"_s;

    // regular decoding
    QTest::newRow("ascii") << u"/tmp/%41%62c"_s << u"/tmp/Abc"_s;
    QTest::newRow("lowercase-hex") << u"%7e%7E"_s << u"~~"_s;
    QTest::newRow("space") << u"/a%20b"_s << u"/a b"_s;
    QTest::newRow("percent") << u"/100%25"_s << u"/100%"_s;
    QTest::newRow("decoded-once") << u"/a%252Fb"_s << u"/a%2Fb"_s;
    QTest::newRow("reserved") << u"%3A%3F%23%5B%5D%40"_s << u":?#[]@"_s;
    QTest::newRow("control") << u"%01%1F%7F"_s << u"\x01\x1f\x7f"_s;
    QTest::newRow("dot-segments") << u"/a/%2E%2E/b"_s << u"/a/../b"_s;

    // UTF-8 is decoded
    QTest::newRow("utf8-2") << u"/caf%C3%A9"_s << u"/caf\u00e9"_s;
    QTest::newRow("utf8-2-lowercase") << u"/caf%c3%a9"_s << u"/caf\u00e9"_s;
    QTest::newRow("utf8-3") << u"%E2%82%AC"_s << u"\u20ac"_s;
    QTest::newRow("utf8-4") << u"%F0%9F%98%80!"_s << u"\U0001F600!"_s;
    QTest::newRow("utf8-max") << u"%F4%8F%BF%BF"_s << u"\U0010FFFF"_s;
    QTest::newRow("utf8-replacement-char") << u"%EF%BF%BD"_s << u"\uFFFD"_s;
    QTest::newRow("utf8-mixed") << u"\u00e9%C3%A9%41"_s << u"\u00e9\u00e9A"_s;

    // non-encoded characters never cause failure
    QTest::newRow("literal-slash") << u"/a/b/"_s << u"/a/b/"_s;
    QTest::newRow("literal-slash-decoded") << u"/a%41/b"_s << u"/aA/b"_s;
    QTest::newRow("literal-backslash") << u"a\\%41"_s << u"a\\A"_s;
    QTest::newRow("literal-nul") << u"a\0%41"_s << u"a\0A"_s;

